package com.bank.cast.service;
import com.bank.cast.model.Account;
import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class AccountLookup {
    private static final Logger log = Logger.getLogger(AccountLookup.class.getName());
    static {
        Handler h = new ConsoleHandler(); h.setFormatter(new BankLogFormatter());
        log.setUseParentHandlers(false); log.addHandler(h);
    }
    // Simulate an index: Map keyed by the string account_no
    private final Map<String, Account> index = new LinkedHashMap<>();
    private final List<Account> all = new ArrayList<>();
    public AccountLookup() {
        add(new Account("SAV2001","Rajesh Kumar", new BigDecimal("1000000.00")));
        add(new Account("CUR3001","Priya Sharma", new BigDecimal("250000.00")));
    }
    private void add(Account a) { all.add(a); index.put(a.getAccountNo(), a); }

    // WRONG: numeric compare forces converting EVERY stored account_no → full scan + parse failures
    public Account lookupWrong(int numericId) {
        int[] touched = {0};
        for (Account a : all) {
            touched[0]++;
            try {
                int asNum = Integer.parseInt(a.getAccountNo().replaceAll("\\D", "")); // implicit cast of column
                if (asNum == numericId) { log.warning(() -> "lookupWrong scanned=" + touched[0]); return a; }
            } catch (NumberFormatException e) {
                log.log(Level.SEVERE, "implicit conversion failed for " + a.getAccountNo(), e);
            }
        }
        log.warning(() -> "lookupWrong scanned=" + touched[0] + " (full scan)");
        return null;
    }

    // RIGHT: string key matches column type → direct index seek, touches 1
    public Account lookupRight(String accountNo) {
        Account a = index.get(accountNo);
        log.info(() -> "lookupRight seek touched=1");
        return a;
    }
}
