package com.bank.cast;
import com.bank.cast.model.Account;
import com.bank.cast.service.AccountLookup;
import java.util.logging.*;

public class CastDemo {
    public static void main(String[] args) {
        AccountLookup svc = new AccountLookup();
        Account wrong = svc.lookupWrong(2001);      // forces column-side conversion
        Account right = svc.lookupRight("SAV2001");  // correct string compare
        System.out.println("wrong -> " + (wrong == null ? "null" : wrong.getAccountNo()));
        System.out.println("right -> " + right.getAccountNo());
    }
}

class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n", r.getMillis(), r.getLevel(), formatMessage(r));
    }
}
